(\forall_S yA)[x:=s]_S=
\begin{cases}
\forall_S yA,&y=x,\\
\forall_S y(A[x:=s]_S),&y\ne x\land y\notin\operatorname{SV}_{ETR}(s),\\
\forall_S z((A[y:=\operatorname{svar}(z)]_S)[x:=s]_S),&y\ne x\land y\in\operatorname{SV}_{ETR}(s),
\end{cases}

(\forall_C YA)[X:=T]_C=
\begin{cases}
\forall_C YA,&Y=X,\\
\forall_C Y(A[X:=T]_C),&Y\ne X\land Y\notin\operatorname{CV}_{ETR}(T),\\
\forall_C Z((A[Y:=\operatorname{cvar}(Z)]_C)[X:=T]_C),&Y\ne X\land Y\in\operatorname{CV}_{ETR}(T),
\end{cases}
